/**
 * Secure implementation of an Atom provider.
 *
 * <p>The original implementation reused a shared {@link Parser} instance and
 * attempted to disable entity resolution inside a synchronized block.  This
 * approach was unsafe because the parser could be used by another thread
 * before the options were applied, leaving the application vulnerable to
 * XML External Entity (XXE) attacks.</p>
 *
 * <p>The patched version creates a fresh {@link Parser} for each request and
 * configures a dedicated {@link ParserOptions} instance with entity resolution
 * explicitly disabled before parsing.  This guarantees that the parser never
 * expands external entities, regardless of concurrency.</p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared {@link Abdera} engine – thread‑safe and inexpensive to reuse. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Whether the parser should try to autodetect the character set. */
    private boolean autodetectCharset;

    // -----------------------------------------------------------------------
    // MessageBodyReader implementation
    // -----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type genericType,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Create a brand‑new parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Configure parser options securely.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Critical: disable external entity resolution to prevent XXE.
        options.setResolveEntities(false);
        // Additional hardening – most parsers honour this, but we set it
        // explicitly for completeness.
        options.setExpandEntities(false);

        // Parse the input using the pre‑configured options.
        Document<T> doc;
        try {
            doc = parser.parse(entityStream, options);
        } catch (RuntimeException e) {
            // Convert any parsing exception to an IOException as required by the
            // JAX‑RS contract.
            throw new IOException("Failed to parse Atom XML payload", e);
        }

        // The document is guaranteed to be non‑null; return its root element.
        return doc.getRoot();
    }

