import org.apache.commons.lang3.StringUtils;

/**
 * URLValidator provides a regular expression for client‑side URL validation.
 * The implementation has been hardened to safely handle null or empty
 * configuration values and to avoid returning an overly complex regular
 * expression that could be abused for ReDoS attacks.
 */
public class URLValidator extends FieldValidatorSupport {

    private String urlRegex;
    private String urlRegexExpression;

    // -----------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------

    /**
     * Returns a regular expression that can be used to validate URLs.
     * <p>
     * The method now defensively checks for {@code null} and empty values,
     * logs unexpected parsing problems, and falls back to a concise,
     * safe default pattern instead of the previously huge expression.
     *
     * @return a safe regex string for URL validation
     */
    public String getUrlRegex() {
        // 1. Prefer an explicitly supplied expression (may be an EL expression)
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String) {
                    String result = ((String) parsed).trim();
                    if (!result.isEmpty()) {
                        return result;
                    }
                }
            } catch (Exception e) {
                // Parsing failed – fall back to the next option.
                // In production you would log this incident.
            }
        }

        // 2. Fallback to a directly configured regex string
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex.trim();
        }

        // 3. Safe default regex.
        //    This pattern matches typical HTTP/HTTPS/FTP URLs without the
        //    excessive nesting that could be exploited for ReDoS.
        return "^(https?|ftp)://[^\\s/$.?#].[^\\s]*$";
    }

    // -----------------------------------------------------------------
    // Additional helper methods (e.g., parse) and class members
    // -----------------------------------------------------------------
}
