import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods ...

    /**
     * Allocates a {@link File} inside the given {@code dir} using the supplied {@code name}.
     * <p>
     * The method sanitises the {@code name} to prevent directory‑traversal attacks.
     * It removes any query string (everything after a {@code '?'}) and then verifies,
     * via canonical paths, that the resulting file resides within {@code dir}.
     * If the check fails an {@link IllegalArgumentException} is thrown.
     * <p>
     * If a file with the desired name already exists, a numeric suffix is added
     * (e.g. {@code name-2.ext}) until a free name is found.
     *
     * @param dir  the directory in which the file must be created; must not be {@code null}
     * @param name the requested file name; must not be {@code null} or empty
     * @return a {@link File} object that points to a non‑existent file inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid,
     *                                  or if a path‑traversal attempt is detected
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Strip any query part (e.g. "file.txt?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Basic sanity check – empty after stripping
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be empty");
        }

        // Resolve the file against the target directory and normalise the path
        File file = new File(dir, name);
        try {
            String canonicalDir = dir.getCanonicalPath();
            String canonicalFile = file.getCanonicalPath();

            // Ensure the resolved file is inside the intended directory.
            // Adding a separator guarantees that "/tmp/dir2" does not match "/tmp/dir".
            if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
                throw new IllegalArgumentException(
                        "Path traversal attempt detected: file resolves outside the target directory");
            }
        } catch (IOException e) {
            // If we cannot resolve canonical paths, fail fast.
            throw new IllegalArgumentException("Unable to resolve file paths", e);
        }

        // If a file with the same name already exists, generate a new unique name.
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            file = new File(dir, newName);
            // Re‑check the canonical path for the newly generated name.
            try {
                String canonicalFile = file.getCanonicalPath();
                String canonicalDir = dir.getCanonicalPath();
                if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
                    throw new IllegalArgumentException(
                            "Generated file name escaped the target directory");
                }
            } catch (IOException e) {
                throw new IllegalArgumentException("Unable to resolve generated file path", e);
            }
        }

        // Ensure the parent directory hierarchy exists.
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalStateException("Failed to create directories for " + parent);
        }

        return file;
    }

    // other methods ...

}
