     * @return a normalised path that starts with a single '/', or {@code null}
     *         if the input was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Find the first character that is not a leading slash.
        int firstNonSlash = 0;
        while (firstNonSlash < path.length() && path.charAt(firstNonSlash) == '/') {
            firstNonSlash++;
        }

        // The remainder of the path after stripping leading slashes.
        String remainder = path.substring(firstNonSlash);

        // If the remainder is empty, the path consisted solely of slashes.
        // In that case we return a single slash.
        if (remainder.isEmpty()) {
            return "/";
        }

        // Prepend exactly one leading slash.
        return '/' + remainder;
