 * attacks.  Only a predefined whitelist of JSP pages is accepted; any other
 * input results in a safe default page.
 */
public class DefaultURLConstructor implements URLConstructor {

    /** Whitelisted forward pages that may be returned by {@link #getForwardPage}. */
    private static final Set<String> ALLOWED_PAGES;

    static {
        Set<String> pages = new HashSet<>();
        pages.add("Wiki.jsp");
        pages.add("PageInfo.jsp");
        pages.add("Edit.jsp");
        pages.add("View.jsp");
        // add any other legitimate forward pages here
        ALLOWED_PAGES = Collections.unmodifiableSet(pages);
    }

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Returns the JSP page that should be used for forwarding.
     *
     * <p>The original implementation returned {@code request.getPathInfo()}
     * directly, which allowed an attacker to supply arbitrary path values such
     * as {@code "/../../WEB-INF/web.xml"} and potentially trigger a path‑traversal
     * attack.  This patched version normalises the supplied path, removes any
     * traversal sequences, and validates the result against a strict whitelist
     * of allowed pages.  If the supplied value is missing, malformed, or not
     * whitelisted, a safe default page ("Wiki.jsp") is returned.</p>
     *
     * @param request the HTTP request that triggered the forward
     * @return a safe JSP page name (e.g., "Wiki.jsp")
     */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        // 1. Retrieve raw path info; may be {@code null}
        String rawPath = request.getPathInfo();
        if (rawPath == null) {
            return "Wiki.jsp"; // default safe page
        }

        // 2. Normalise the path to eliminate sequences like "../"
        //    Paths.get handles both '/' and '\' on all platforms.
        Path normalizedPath = Paths.get(rawPath).normalize();

        // 3. Convert back to a string and strip any leading file‑separator.
        String normalized = normalizedPath.toString();
        while (normalized.startsWith("/") || normalized.startsWith("\\")) {
            normalized = normalized.substring(1);
        }

        // 4. Reject any path that still contains traversal or additional separators.
        if (normalized.contains("..") || normalized.contains("/") || normalized.contains("\\")) {
            return "Wiki.jsp";
        }

        // 5. Validate against the whitelist of allowed JSP pages.
        if (ALLOWED_PAGES.contains(normalized)) {
            return normalized;
        }

        // 6. Fallback to the default page if validation fails.
        return "Wiki.jsp";
    }

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------
}
