import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;

class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from {@code in} into {@code out}.
     *
     * <p>The original implementation could enter an infinite loop when the
     * underlying {@link InputStream} returned {@code -1} (end‑of‑stream) or
     * when malformed data caused more bytes to be written than the size of
     * {@code out}.  This version validates every read, respects the remaining
     * space in the output buffer and fails fast with a clear exception if the
     * input is not well‑formed.</p>
     *
     * @param in  the source of compressed data (must not be {@code null})
     * @param out the destination buffer (must not be {@code null})
     * @throws IOException if an I/O error occurs or the input data is malformed
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        if (in == null) {
            throw new IllegalArgumentException("InputStream must not be null");
        }
        if (out == null) {
            throw new IllegalArgumentException("Output buffer must not be null");
        }

        int position = 0;
        final int total = out.length;

        // Guard against pathological inputs that could otherwise cause an
        // extremely large number of iterations (e.g., a crafted stream that
        // repeatedly writes zero bytes).  The number of iterations needed
        // cannot exceed total * 2 + 10 for a valid stream.
        final int maxIterations = total * 2 + 10;
        int iterations = 0;

        while (position < total) {
            if (iterations++ > maxIterations) {
                throw new IOException("Decompression aborted: too many iterations – possible malformed input");
            }

            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading control byte");
            }

            if (n > 128) {                     // run‑length encoded block
                int repeatCount = n & 0x7F;    // number of repetitions (0‑127)
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeat value");
                }

                // Write only as many bytes as fit into the output buffer.
                int remaining = total - position;
                int toWrite = Math.min(repeatCount, remaining);
                for (int i = 0; i < toWrite; i++) {
                    out[position++] = (byte) value;
                }

                // If the repeat count exceeds the remaining space we have already
                // filled the buffer – the excess bytes are simply ignored because
                // they cannot be stored.
                if (repeatCount > remaining) {
                    // No more room; exit the loop.
                    break;
                }
            } else {                            // literal block
                int literalCount = n;           // number of literal bytes (0‑128)
                int remaining = total - position;
                int toRead = Math.min(literalCount, remaining);

                for (int i = 0; i < toRead; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal data");
                    }
                    out[position++] = (byte) b;
                }

                // If the literal count exceeds the remaining space we have
                // already filled the buffer – discard the surplus input.
                if (literalCount > remaining) {
                    // Consume and discard the remaining bytes of this block to keep the
                    // stream in a consistent state, then break.
                    for (int i = toRead; i < literalCount; i++) {
                        if (in.read() == -1) {
                            throw new EOFException("Unexpected end of stream while discarding excess literals");
                        }
                    }
                    break;
                }
            }
        }

        // If we exit the loop without having filled the buffer, the input was
        // shorter than expected.
        if (position < total) {
            throw new IOException("Decompression failed: insufficient data (expected " + total + " bytes, got " + position + ")");
        }
