import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.charset.CharsetEncoder;
import java.nio.charset.CoderResult;

class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // other methods ...

    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        CharBuffer tmp = null;
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        // safeguard against a pathological input that would otherwise cause an endless loop
        final int maxAttempts = name.length() * 2 + 10; // generous bound, still O(n)
        int attempts = 0;

        while (cb.remaining() > 0) {
            if (++attempts > maxAttempts) {
                throw new IllegalStateException("Encoding failed to make progress after "
                        + maxAttempts + " iterations – possible malformed input");
            }

            final CoderResult res = enc.encode(cb, out, false);

            if (res.isUnderflow()) {
                // all input consumed – exit the loop
                break;
            }

            if (res.isOverflow()) {
                // not enough space in the output buffer – grow it and retry
                final int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
                continue;
            }

            if (res.isUnmappable() || res.isMalformed()) {
                // ensure there is enough room for the surrogate representation
                final int spaceForSurrogate = estimateIncrementalEncodingSize(enc, 6 * res.length());
                if (spaceForSurrogate > out.remaining()) {
                    int charCount = 0;
                    for (int i = cb.position(); i < cb.limit(); i++) {
                        charCount += !enc.canEncode(cb.get(i)) ? 6 : 1;
                    }
                    final int totalExtraSpace = estimateIncrementalEncodingSize(enc, charCount);
                    out = ZipEncodingHelper.growBufferBy(out, totalExtraSpace - out.remaining());
                }

                // allocate a temporary buffer for surrogate encoding once
                if (tmp == null) {
                    tmp = CharBuffer.allocate(6);
                }

                // encode each problematic character as a surrogate sequence
                for (int i = 0; i < res.length(); ++i) {
                    // cb.get() advances the CharBuffer position, guaranteeing progress
                    out = encodeFully(enc, encodeSurrogate(tmp, cb.get()), out);
                }
                continue;
            }

            // any other result is an error – propagate it
            res.throwException();
        }

        // final flush – encode any remaining state and signal end‑of‑input
        enc.encode(cb, out, true);
        out.limit(out.position());
        out.rewind();
        return out;
    }

    // other helper methods (estimateIncrementalEncodingSize, encodeFully, encodeSurrogate, …)
}
