    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // 1) Already a Locale – safe to return as‑is
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already Locale): {}", locale);
            return locale;
        }

        // 2) Only accept String values; reject any other object types
        if (!(requestedLocale instanceof String)) {
            LOG.warn("Unsupported locale parameter type: {}", requestedLocale.getClass().getName());
            return null;
        }

        String localeStr = ((String) requestedLocale).trim();

        // 3) Whitelist validation – allow only language (2‑3 letters) and optional
        //    country (2‑3 letters) separated by '_' (e.g. "en", "en_US").
        //    This prevents characters that could be interpreted as script.
        final Pattern LOCALE_PATTERN = Pattern.compile("^[a-zA-Z]{2,3}(_[a-zA-Z]{2,3})?$");
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Invalid locale format received: \"{}\" – rejected", localeStr);
            return null;
        }

        // 4) Convert the validated string to a Locale. Any unexpected exception
        //    is caught and logged; the method then returns null.
