     *   <li>Negotiates STARTTLS securely.</li>
     *   <li>Injects the authentication information into the context.</li>
     *   <li>Executes a lightweight LDAP operation (read of the root DSE) to
     *       trigger an actual bind, ensuring the server validates the credentials.</li>
     *   <li>Handles all error paths, closes resources, and logs detailed messages.</li>
     * </ul>
     *
     * @param ldapContextFactory the factory that provides LDAP connection settings
     * @param principal          the bind DN (or user name) to authenticate with
     * @param credentials        the password (or other credentials) for the bind DN
     * @return a fully authenticated {@link LdapContext}
     * @throws NamingException if any LDAP operation fails, including authentication failures
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {
        // --------------------------------------------------------------------
        // 1. Basic argument validation – prevents null‑pointer attacks and
        //    makes the contract explicit.
        // --------------------------------------------------------------------
        if (principal == null) {
            throw new IllegalArgumentException("LDAP principal must not be null");
        }
        if (credentials == null) {
            throw new IllegalArgumentException("LDAP credentials must not be null");
        }

        // --------------------------------------------------------------------
        // 2. Build the initial environment (no authentication yet – we
        //    first need to establish a TLS tunnel).
        // --------------------------------------------------------------------
        JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiFactory.getUrl());

        LdapContext ctx = null;
        StartTlsResponse tls = null;

        try {
            // ----------------------------------------------------------------
            // 3. Create the raw context and negotiate STARTTLS.
            // ----------------------------------------------------------------
            ctx = new InitialLdapContext(env, null);
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate(); // May throw IOException

            // ----------------------------------------------------------------
            // 4. Inject authentication information *after* the TLS tunnel is
            //    established.
            // ----------------------------------------------------------------
            ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                                 jndiFactory.getAuthenticationMechanism());
            ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
            ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

