import java.io.InputStream;
import javax.xml.XMLConstants;
import javax.xml.transform.Source;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamSource;

/**
 * Secure creation of a {@link Transformer} from an XSLT template.
 *
 * <p>The method now:
 * <ul>
 *   <li>Uses a fresh {@link TransformerFactory} for each call to avoid state leakage.</li>
 *   <li>Enables {@code FEATURE_SECURE_PROCESSING} to enforce processing limits.</li>
 *   <li>Restricts external entity and stylesheet access via
 *       {@code ACCESS_EXTERNAL_DTD} and {@code ACCESS_EXTERNAL_STYLESHEET}.</li>
 *   <li>Validates the supplied {@link InputStream} and closes it safely with
 *       try‑with‑resources.</li>
 *   <li>Wraps any {@link TransformerConfigurationException} in a domain‑specific
 *       {@link ProcessingFailedException}.</li>
 * </ul>
 *
 * @param templateStream InputStream containing the XSLT template (must not be {@code null})
 * @return a securely configured {@link Transformer}
 * @throws IOException if an I/O error occurs while closing the stream
 * @throws ProcessingFailedException if the XSLT cannot be compiled
 */
private static Transformer createTransformer(InputStream templateStream) throws IOException {
    if (templateStream == null) {
        throw new IllegalArgumentException("XSLT template stream must not be null");
    }

    // Use a fresh factory for each transformation to avoid cross‑contamination of settings.
    TransformerFactory factory = TransformerFactory.newInstance();

    // Enable secure processing – limits processing to safe defaults.
    try {
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    } catch (TransformerConfigurationException e) {
        // If the implementation does not support the feature, fail fast.
        throw new ProcessingFailedException("Secure processing feature not supported", e);
    }

    // Disallow any external DTD or stylesheet access.
    try {
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
    } catch (IllegalArgumentException ignored) {
        // Some factories may not support the attribute; ignore as the secure flag already limits exposure.
    }
    try {
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
    } catch (IllegalArgumentException ignored) {
        // Same rationale as above.
    }

    // Ensure the InputStream is closed regardless of success or failure.
    try (InputStream is = templateStream) {
        Source xsltSource = new StreamSource(is);
        return factory.newTransformer(xsltSource);
    } catch (TransformerConfigurationException e) {
        throw new ProcessingFailedException("Failed to create XSLT template", e);
    }
}
