import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Secure expansion of archive entries.
 *
 * This implementation mitigates path‑traversal attacks by:
 *   • Rejecting absolute entry names.
 *   • Normalising the resolved path and ensuring it stays within the
 *     canonical target directory (using {@code Path#startsWith} on real paths).
 *   • Creating directories with {@code Files.createDirectories} which
 *     safely handles intermediate directories.
 *   • Writing file data with {@code Files.newOutputStream} using explicit
 *     {@code CREATE} and {@code TRUNCATE_EXISTING} options.
 */
public class Expander {

    // other methods ...

    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to a real (canonical) path without following
        // symbolic links. This is the trusted base for all extracted entries.
        Path targetDirPath = targetDirectory.toPath()
                                             .toRealPath(LinkOption.NOFOLLOW_LINKS);

        ArchiveEntry nextEntry;
        while ((nextEntry = supplier.getNextReadableEntry()) != null) {
            String entryName = nextEntry.getName();

            // -----------------------------------------------------------------
            // 1. Basic validation of the entry name
            // -----------------------------------------------------------------
            // Reject absolute paths – they would bypass the target directory.
            Path entryPath = Paths.get(entryName);
            if (entryPath.isAbsolute()) {
                throw new IOException("Archive entry has absolute path: " + entryName);
            }

            // Resolve the entry against the target directory and normalise it.
            // Normalisation removes any ".." or "." segments.
            Path resolvedPath = targetDirPath.resolve(entryPath).normalize();

            // -----------------------------------------------------------------
            // 2. Ensure the resolved path is still inside the target directory
            // -----------------------------------------------------------------
            // Using Path#startsWith on real paths prevents crafted strings such as
            // "/tmp/target/../etc/passwd" from escaping the intended directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName
                        + " would create file outside of " + targetDirectory);
            }

            // -----------------------------------------------------------------
            // 3. Create directories or write file data
            // -----------------------------------------------------------------
            if (nextEntry.isDirectory()) {
                // Create the directory (including any missing parents).
                Files.createDirectories(resolvedPath);
            } else {
                // Ensure the parent directory exists.
                Files.createDirectories(resolvedPath.getParent());

                // Write the entry's data to the file.
                try (OutputStream out = Files.newOutputStream(resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }
        }
    }

    // other methods ...

}
