     * Implementation of read for STORED entries.
     *
     * <p>This method has been hardened against malformed ZIP archives that
     * could otherwise cause an infinite read loop.  The fixes include:</p>
     * <ul>
     *   <li>Explicit handling of {@code length == 0} as required by the
     *       {@link InputStream} contract.</li>
     *   <li>Graceful handling of entries with an unknown size
     *       (size &lt; 0).  In that case we rely on the underlying stream
     *       reaching EOF.</li>
     *   <li>Defensive checks for {@code InputStream.read()} returning {@code 0}
     *       – a non‑standard but possible behaviour that would otherwise lead
     *       to a never‑advancing buffer and an infinite loop.</li>
     *   <li>Additional sanity checks to ensure we never read past the
     *       declared size of the entry and that we correctly signal EOF
     *       when the declared size has been satisfied.</li>
     * </ul>
     */
    private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
        // Per InputStream contract: a zero‑length read must return 0 immediately.
        if (length == 0) {
            return 0;
        }

        // Entries that use a data descriptor are cached in {@code lastStoredEntry}.
        if (current.hasDataDescriptor) {
            if (lastStoredEntry == null) {
                readStoredEntry();               // fills {@code lastStoredEntry}
            }
            return lastStoredEntry.read(buffer, offset, length);
        }

        // Size may be unknown (e.g., malformed archive).  Treat negative sizes as “unknown”.
        final long csize = current.entry.getSize();
        final boolean sizeKnown = csize >= 0;

        // If we already read the declared size, signal EOF.
        if (sizeKnown && current.bytesRead >= csize) {
            return -1;
        }

        // Refill the internal buffer when it is exhausted.
        if (buf.position() >= buf.limit()) {
            buf.position(0);
            final int l = in.read(buf.array());

            // Normal EOF from the underlying stream.
            if (l == -1) {
                return -1;
            }

            // Defensive: some non‑blocking streams may return 0 without reaching EOF.
            // Treat this as EOF to avoid an infinite loop.
            if (l == 0) {
                return -1;
            }

            buf.limit(l);
            count(l);
            current.bytesReadFromStream += l;
        }

        // Determine the maximum number of bytes we can safely return.
        int toRead = Math.min(buf.remaining(), length);
        if (sizeKnown) {
            final long remaining = csize - current.bytesRead;
            if (remaining <= 0) {
                return -1;                         // Declared size already satisfied.
            }
            if (remaining < toRead) {
                toRead = (int) remaining;        // Do not exceed the entry size.
            }
        }

        // If, after all checks, there is nothing to read, signal EOF.
        if (toRead <= 0) {
            return -1;
        }

        // Transfer bytes from the internal buffer to the caller's buffer.
        buf.get(buffer, offset, toRead);
        current.bytesRead += toRead;
        return toRead;
    }
